solution:
public class ConversionesBasicas {
    public static void main(String[] args) {
        int entero = 250;

        // Widening: int → double
        double decimal = entero;
        System.out.println("int " + entero + " → double: " + decimal);

        // Narrowing: double → int
        double pi = 3.14159;
        int truncado = (int) pi;
        System.out.println("double " + pi + " → int: " + truncado);

        // Narrowing: int → byte (desbordamiento)
        int grande = 130;
        byte pequeno = (byte) grande;
        System.out.println("int " + grande + " → byte: " + pequeno);

        // char → int (valor Unicode)
        char letra = 'Z';
        int valorUnicode = letra;
        System.out.println("char '" + letra + "' → int: " + valorUnicode);
    }
}

