solution:
public class ConvertidorTemperatura {
    public static void main(String[] args) {
        String[] temperaturas = {"37.5", "-10", "abc", "100"};
        int exitosas = 0;

        for (String tempStr : temperaturas) {
            System.out.print("Convirtiendo '" + tempStr + "'... ");

            try {
                double celsius = Double.parseDouble(tempStr);

                double fahrenheit = celsius * 9.0 / 5.0 + 32;
                double kelvin = celsius + 273.15;

                System.out.println("✅ OK");
                System.out.printf("  %.1f°C = %.1f°F = %.2fK%n",
                    celsius, fahrenheit, kelvin);
                System.out.printf("  Truncado: %d°C, %d°F, %dK%n",
                    (int) celsius, (int) fahrenheit, (int) kelvin);

                exitosas++;
            } catch (NumberFormatException e) {
                System.out.println("❌ No es un número válido");
            }
            System.out.println();
        }

        System.out.println("Conversiones exitosas: " + exitosas + "/" + temperaturas.length);
    }
}
